@startuml

class Product {
  + name : string
  + description : string
  + net_price : float
}

class Manufacturer {
  + name : string
}

class Country {
  + name : string
  + vat_rate : float
  + currency : string
  + conversion_rate_to_euro : float
}

class Representative {
  + first_name : string
  + last_name : string
  + social_security_number : string
  + telephone_number : string
  + email_address : string
}

class Customer {
  + name : string
  + address : string
  + telephone_number : string
  + email_address : string
}

class Order {
  + order_id : string
  + order_quantity : int
  + order_date : date
  + desired_delivery_date : date
}

Manufacturer "1" -- "0..*" Product : manufactures
Product "*" -- "0..*" Country : is_sold_in
Representative "1" -- "1" Country : is_responsible_for
Representative "1" -- "0..*" Order : places
Customer "1" -- "0..*" Order : places
Order "0..*" -- "1" Product : refers_to
Customer "*" -- "*" Country : resells_in

@enduml

